function svgSticker(ctx,symbol){
  ctx.save();ctx.scale(1/100,1/100);ctx.lineWidth=2.5;ctx.strokeStyle='#2a2426';
  if(symbol==='pumpkin') {ctx.fillStyle='#60452c';ctx.beginPath();ctx.moveTo(-4,-25);ctx.quadraticCurveTo(-9,-50,10,-49);ctx.lineTo(16,-39);ctx.quadraticCurveTo(0,-35,4,-25);ctx.fill();[-25,25,0].forEach((x,i)=>{const pumpkinGlow=ctx.createRadialGradient(x-8,-12,1,x,6,42);pumpkinGlow.addColorStop(0,['#ffc66b','#e58b32','#ffb34f'][i]);pumpkinGlow.addColorStop(1,['#dc641f','#ac491b','#e87c22'][i]);ctx.fillStyle=pumpkinGlow;ctx.beginPath();ctx.ellipse(x,6,i===2?22:26,38,0,0,Math.PI*2);ctx.fill();ctx.stroke()});ctx.fillStyle='#332721';ctx.beginPath();ctx.moveTo(-30,-7);ctx.lineTo(-15,-19);ctx.lineTo(-9,-2);ctx.closePath();ctx.moveTo(10,-2);ctx.lineTo(18,-19);ctx.lineTo(32,-7);ctx.closePath();ctx.fill();ctx.beginPath();ctx.moveTo(-27,17);ctx.lineTo(-12,22);ctx.lineTo(-9,16);ctx.lineTo(4,25);ctx.lineTo(9,18);ctx.lineTo(28,16);ctx.quadraticCurveTo(1,49,-27,17);ctx.fill();}
  else if(symbol==='ghost'){ctx.fillStyle='#f3f0df';ctx.beginPath();ctx.moveTo(-36,43);ctx.lineTo(-30,-6);ctx.bezierCurveTo(-30,-53,30,-53,30,-6);ctx.lineTo(40,44);ctx.lineTo(23,33);ctx.lineTo(10,46);ctx.lineTo(-3,34);ctx.lineTo(-20,46);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#343137';[-10,12].forEach(x=>{ctx.beginPath();ctx.ellipse(x,-5,4,8,0,0,Math.PI*2);ctx.fill()});ctx.beginPath();ctx.ellipse(1,16,5,7,0,0,Math.PI*2);ctx.fill();}
  else if(symbol==='bat'){ctx.fillStyle='#29242d';ctx.beginPath();ctx.moveTo(0,8);ctx.lineTo(-9,-12);ctx.lineTo(-48,-35);ctx.quadraticCurveTo(-44,-7,-50,15);ctx.quadraticCurveTo(-34,0,-26,25);ctx.quadraticCurveTo(-13,10,0,36);ctx.quadraticCurveTo(13,10,26,25);ctx.quadraticCurveTo(34,0,50,15);ctx.quadraticCurveTo(44,-7,48,-35);ctx.lineTo(9,-12);ctx.closePath();ctx.fill();ctx.fillStyle='#f1c972';ctx.fillRect(-5,7,3,3);ctx.fillRect(3,7,3,3);}
  else if(symbol==='moon'){const g=ctx.createRadialGradient(-15,-18,3,0,0,47);g.addColorStop(0,'#f6e9d1');g.addColorStop(1,'#b9a894');ctx.fillStyle=g;ctx.beginPath();ctx.arc(0,0,45,0,Math.PI*2);ctx.fill();ctx.fillStyle='#8c7e7340';[[-18,-20,11],[18,4,14],[-9,20,8],[17,-25,6],[-28,7,7]].forEach(([x,y,r])=>{ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill()});}
  else {ctx.fillStyle='#e6c887';ctx.beginPath();for(let i=0;i<10;i++){const a=i*Math.PI/5-Math.PI/2,r=i%2?21:48;ctx.lineTo(Math.cos(a)*r,Math.sin(a)*r)}ctx.closePath();ctx.fill();ctx.stroke();}ctx.restore();
}
function cover(ctx,img,w,h,mono){ctx.save();if(mono)ctx.filter='grayscale(1)';const r=Math.max(w/img.width,h/img.height),sw=w/r,sh=h/r;ctx.drawImage(img,(img.width-sw)/2,(img.height-sh)/2,sw,sh,-w/2,-h/2,w,h);ctx.restore()}
async function renderLayerSlide(canvas,s,format,number=0,total=1){
  const imgs=await Promise.all(s.layers.map(l=>l.type==='photo'?loadImage(l.src):null));canvas.width=1080;canvas.height=format==='story'?1920:format==='square'?1080:1350;
  const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height;ctx.fillStyle=s.bg;ctx.fillRect(0,0,w,h);
  if(s.texture&&s.texture!=='none'){let seed=732;for(let i=0;i<7500;i++){seed=(seed*16807)%2147483647;const x=seed%w;seed=(seed*16807)%2147483647;const y=seed%h;ctx.fillStyle=i%2?'#ffffff09':'#0000000c';ctx.fillRect(x,y,i%3+1,i%3+1)}}
  s.layers.forEach((l,i)=>{ctx.save();ctx.translate(l.x*w/1000,l.y*h/1000);ctx.rotate((l.rotation||0)*Math.PI/180);const lw=l.w*w/1000,lh=l.h*h/1000;
    if(l.type==='photo'){if(l.frame!=='plain'){const pad=lw*.035;ctx.fillStyle='#fffaf0';ctx.shadowColor='#0006';ctx.shadowBlur=12;ctx.shadowOffsetY=5;ctx.fillRect(-lw/2-pad,-lh/2-pad,lw+pad*2,lh+pad*(l.frame==='polaroid'?5:2));ctx.shadowColor='transparent'}if(imgs[i])cover(ctx,imgs[i],lw,lh,l.monochrome);else{ctx.fillStyle=s.bg==='#f78024'?'#ab4e18':'#88817d';ctx.fillRect(-lw/2,-lh/2,lw,lh);const g=ctx.createLinearGradient(-lw/2,-lh/2,lw/2,lh/2);g.addColorStop(0,'#d1c4b9');g.addColorStop(1,'#726c69');ctx.fillStyle=g;ctx.fillRect(-lw/2,-lh/2,lw,lh);ctx.fillStyle='#ffffffaa';ctx.textAlign='center';ctx.font=`${Math.min(lw*.09,32)}px Arial`;ctx.fillText('＋ YOUR PHOTO',0,10,lw*.8)}}
    if(l.type==='text'){let fontSize=l.size*w/1000;const lines=l.text.split('\n');ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillStyle=l.color;ctx.font=`${l.font==='Georgia'?'italic ':''}${l.font==='Impact'?'bold ':''}${fontSize}px ${l.font||'Georgia'}`;while(lines.some(line=>ctx.measureText(line).width>lw)&&fontSize>10){fontSize--;ctx.font=`${l.font==='Georgia'?'italic ':''}${l.font==='Impact'?'bold ':''}${fontSize}px ${l.font||'Georgia'}`}lines.forEach((line,j)=>ctx.fillText(line,0,(j-(lines.length-1)/2)*fontSize*1.1))}
    if(l.type==='sticker'){ctx.scale(lw,lh);svgSticker(ctx,l.symbol)}
    if(l.type==='shape'){ctx.fillStyle=l.color;ctx.fillRect(-lw/2,-lh/2,lw,lh)}
    if(l.type==='border'){ctx.strokeStyle=l.color;ctx.lineWidth=l.pattern==='metal'?20:4;ctx.strokeRect(-lw/2,-lh/2,lw,lh);if(l.pattern==='metal'){ctx.strokeStyle='#f4e4c6';ctx.lineWidth=4;ctx.strokeRect(-lw/2+10,-lh/2+10,lw-20,lh-20);ctx.strokeStyle='#584c40';ctx.lineWidth=8;ctx.strokeRect(-lw/2-12,-lh/2-12,lw+24,lh+24)}else{const steps=22;for(let j=0;j<=steps;j++){const x=-lw/2+j*lw/steps;for(const y of [-lh/2,lh/2]){ctx.beginPath();ctx.ellipse(x,y,12,20,0,0,Math.PI*2);ctx.stroke()}const y=-lh/2+j*lh/steps;for(const x of [-lw/2,lw/2]){ctx.beginPath();ctx.ellipse(x,y,20,12,0,0,Math.PI*2);ctx.stroke()}}ctx.lineWidth=2;ctx.strokeRect(-lw/2+23,-lh/2+23,lw-46,lh-46)}}ctx.restore();
  });
}
draw=async function(){if(!isLayered()){outline.style.display='none';return originalDraw()}const ticket=++layerPaint,s=structuredClone(design.slides[current]),format=design.format;const temp=document.createElement('canvas');await renderLayerSlide(temp,s,format,current,design.slides.length);if(ticket!==layerPaint)return;const c=$('#canvas');c.width=temp.width;c.height=temp.height;c.getContext('2d').drawImage(temp,0,0);positionOutline()};
function positionOutline(){const l=chosen(),c=$('#canvas'),area=$('.canvas-area');if(!l||!isLayered()||!$('#editor').open){outline.style.display='none';return}const box=c.getBoundingClientRect(),parent=area.getBoundingClientRect();const scale=Math.min(box.width/c.width,box.height/c.height),width=c.width*scale,height=c.height*scale,left=box.left+(box.width-width)/2,top=box.top+(box.height-height)/2;Object.assign(outline.style,{display:'block',left:(left-parent.left+l.x/1000*width-l.w/2000*width)+'px',top:(top-parent.top+l.y/1000*height-l.h/2000*height)+'px',width:l.w/1000*width+'px',height:l.h/1000*height+'px',transform:`rotate(${l.rotation||0}deg)`})}
function layerLabel(l){return l.type==='text'?l.text.replaceAll('\n',' '):l.type==='photo'?'Photo'+(l.monochrome?' · B&W':''):l.type==='sticker'?l.symbol:l.type==='border'?'Decorative frame':'Paper backing'}
function refreshLayers(){const s=design.slides[current];$('#layer-list').replaceChildren();[...s.layers].reverse().forEach(l=>{const b=document.createElement('button');b.dataset.layerId=l.id;b.className=l.id===selectedLayer?'selected':'';const span=document.createElement('span');span.textContent=layerLabel(l);const small=document.createElement('small');small.textContent=l.type;b.append(span,small);b.onclick=()=>{selectedLayer=l.id;refreshLayers();positionOutline()};$('#layer-list').append(b)});properties()}
function control(label,type,value,change,opts={}){const wrap=document.createElement('label');wrap.textContent=label;const input=document.createElement(type==='textarea'?'textarea':type==='select'?'select':'input');input.setAttribute('aria-label',label);if(input.tagName==='INPUT')input.type=type;const {options,...attributes}=opts;Object.assign(input,attributes);if(type==='select')opts.options.forEach(([v,t])=>{const option=document.createElement('option');option.value=v;option.textContent=t;input.append(option)});input.value=value;input.oninput=()=>{change(input.value);draw()};wrap.append(input);return wrap}
function properties(){const el=$('#layer-properties');el.replaceChildren();const l=chosen();if(!l){el.textContent='Select a layer to edit it.';return}
  if(l.type==='text'){el.append(control('Text','textarea',l.text,v=>{l.text=v;const row=[...$('#layer-list').querySelectorAll('button')].find(b=>b.dataset.layerId===l.id);if(row)row.querySelector('span').textContent=layerLabel(l)}),control('Typeface','select',l.font,v=>l.font=v,{options:[['Georgia','Editorial serif'],['Impact','Bold headline'],['Arial','Clean sans']]}),control('Text color','color',l.color,v=>l.color=v),control('Font size','range',l.size,v=>{l.size=+v;l.h=Math.max(l.h,l.size*1.5)},{min:15,max:180}));}
  if(l.type==='photo'){const b=document.createElement('button');b.className='outline';b.textContent=l.src?'Replace photo':'Upload photo';b.onclick=()=>{uploadMode='replace';multiFile.click()};el.append(b,control('Frame','select',l.frame,v=>l.frame=v,{options:[['plain','No frame'],['white','White border'],['polaroid','Polaroid']]}),control('Photo treatment','select',l.monochrome?'mono':'color',v=>l.monochrome=v==='mono',{options:[['color','Original color'],['mono','Black & white']]}));}
  if(l.type==='shape'||l.type==='border')el.append(control('Element color','color',l.color,v=>l.color=v));
  el.append(control('Width','range',l.w,v=>l.w=+v,{min:40,max:1200}),control('Height','range',l.h,v=>l.h=+v,{min:30,max:1200}),control('Rotation','range',l.rotation||0,v=>l.rotation=+v,{min:-180,max:180}));
  const actions=document.createElement('div');actions.className='layer-actions';[['↑ Forward',()=>L.reorder(design.slides[current].layers,selectedLayer,1)],['↓ Back',()=>L.reorder(design.slides[current].layers,selectedLayer,-1)],['Duplicate',()=>{const copy=structuredClone(l);copy.id=crypto.randomUUID();copy.x=Math.min(1000,copy.x+25);copy.y=Math.min(1000,copy.y+25);design.slides[current].layers.push(copy);selectedLayer=copy.id}],['Delete',()=>{design.slides[current].layers=design.slides[current].layers.filter(x=>x.id!==selectedLayer);selectedLayer=null}]].forEach(([label,fn])=>{const b=document.createElement('button');b.textContent=label;b.onclick=()=>{fn();refreshLayers();draw()};actions.append(b)});el.append(actions);
}
sync=function(){originalSync();const layered=isLayered();$('#editor').classList.toggle('editor-layered',layered);legacy.hidden=layered;panel.hidden=!layered;hint.hidden=!layered;exportAll.hidden=!layered;previewButton.hidden=!layered;collectionBanner.hidden=view!=='discover';if(!layered)return;const s=design.slides[current];if(!s.layers.some(l=>l.id===selectedLayer))selectedLayer=null;$('#layer-bg').value=s.bg;$('#layer-texture').value=s.texture||'none';$('#layer-format').value=design.format;refreshLayers();$('#layer-remove-slide').disabled=design.slides.length===1;$('#slides').querySelectorAll('button').forEach((b,i)=>{b.textContent='';b.setAttribute('aria-label',`Slide ${i+1}`);const c=document.createElement('canvas');b.append(c);renderLayerSlide(c,design.slides[i],design.format,i,design.slides.length)});draw()};
