[['pumpkin','🎃'],['ghost','👻'],['bat','🦇'],['moon','☾'],['star','✦']].forEach(([symbol,label])=>{const b=document.createElement('button');b.textContent=label;b.setAttribute('aria-label','Add '+symbol+' sticker');b.onclick=()=>{const l=L.sticker(symbol,500,500);l.h=l.w*1080/(design.format==='story'?1920:design.format==='square'?1080:1350);design.slides[current].layers.push(l);selectedLayer=l.id;refreshLayers();draw()};$('.sticker-picker').append(b)});
$('#layer-bg').oninput=e=>{design.slides[current].bg=e.target.value;draw()};$('#layer-texture').onchange=e=>{design.slides[current].texture=e.target.value;draw()};$('#layer-format').onchange=e=>{design.format=e.target.value;const ratio=1080/(design.format==='story'?1920:design.format==='square'?1080:1350);design.slides.forEach(s=>s.layers.forEach(l=>{if(l.type==='sticker')l.h=l.w*ratio}));$('#format').value=design.format;sync()};$('#layer-add-slide').onclick=()=>{if(design.slides.length>=20)return toast('A carousel can have up to 20 slides.');const s=structuredClone(design.slides[current]);s.layers.forEach(l=>l.id=crypto.randomUUID());design.slides.push(s);current=design.slides.length-1;selectedLayer=null;sync()};$('#layer-remove-slide').onclick=()=>{if(design.slides.length===1)return;design.slides.splice(current,1);current=Math.min(current,design.slides.length-1);selectedLayer=null;sync()};
async function fileImage(file){if(!file.type.startsWith('image/'))throw Error('Choose an image file.');const url=URL.createObjectURL(file);try{const img=await loadImage(url);if(!img)throw Error('Could not open this photo. Try JPG or PNG.');const c=document.createElement('canvas'),r=Math.min(1,1400/Math.max(img.width,img.height));c.width=Math.round(img.width*r);c.height=Math.round(img.height*r);c.getContext('2d').drawImage(img,0,0,c.width,c.height);return c.toDataURL(file.type==='image/png'?'image/png':'image/jpeg',.87)}finally{cache.delete(url);URL.revokeObjectURL(url)}}
