previewButton.onclick=()=>{previewIndex=current;postPreview.showModal();previewSlide()};postPreview.querySelector('.icon').onclick=()=>postPreview.close();const nav=postPreview.querySelectorAll('.preview-nav button');nav[0].onclick=()=>{previewIndex=(previewIndex-1+design.slides.length)%design.slides.length;previewSlide()};nav[1].onclick=()=>{previewIndex=(previewIndex+1)%design.slides.length;previewSlide()};postPreview.addEventListener('keydown',e=>{if(e.key==='ArrowRight')nav[1].click();if(e.key==='ArrowLeft')nav[0].click()});let touchStart=null;postPreview.addEventListener('touchstart',e=>touchStart=e.touches[0].clientX,{passive:true});postPreview.addEventListener('touchend',e=>{if(touchStart===null)return;const d=e.changedTouches[0].clientX-touchStart;if(Math.abs(d)>40)nav[d>0?0:1].click();touchStart=null},{passive:true});
exportAll.onclick=async()=>{exportAll.disabled=true;const savedCurrent=current;try{const files=[];for(let i=0;i<design.slides.length;i++){const c=document.createElement('canvas');await renderLayerSlide(c,design.slides[i],design.format,i,design.slides.length);const blob=await new Promise(resolve=>c.toBlob(resolve,'image/png'));if(!blob)throw Error('PNG export failed');files.push({name:`slide-${String(i+1).padStart(2,'0')}.png`,data:new Uint8Array(await blob.arrayBuffer())})}const blob=zipStore(files),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=($('#design-name').value||'social-poster').replace(/[^a-z0-9-]/gi,'-')+'.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);save(false);toast('All slides exported in a ZIP.')}catch{toast('Export failed. Try uploading local photos.')}finally{current=savedCurrent;exportAll.disabled=false}};
function zipStore(files){const parts=[],central=[];let offset=0;const enc=new TextEncoder();const u16=(v,o,n)=>v.setUint16(o,n,true),u32=(v,o,n)=>v.setUint32(o,n,true);const crc=bytes=>{let n=0xffffffff;for(const byte of bytes){n^=byte;for(let j=0;j<8;j++)n=(n>>>1)^((n&1)?0xedb88320:0)}return(n^0xffffffff)>>>0};for(const f of files){const name=enc.encode(f.name),hash=crc(f.data),h=new Uint8Array(30+name.length),v=new DataView(h.buffer);u32(v,0,0x04034b50);u16(v,4,20);u32(v,14,hash);u32(v,18,f.data.length);u32(v,22,f.data.length);u16(v,26,name.length);h.set(name,30);parts.push(h,f.data);const d=new Uint8Array(46+name.length),dv=new DataView(d.buffer);u32(dv,0,0x02014b50);u16(dv,4,20);u16(dv,6,20);u32(dv,16,hash);u32(dv,20,f.data.length);u32(dv,24,f.data.length);u16(dv,28,name.length);u32(dv,42,offset);d.set(name,46);central.push(d);offset+=h.length+f.data.length}const size=central.reduce((n,a)=>n+a.length,0),end=new Uint8Array(22),ev=new DataView(end.buffer);u32(ev,0,0x06054b50);u16(ev,8,files.length);u16(ev,10,files.length);u32(ev,12,size);u32(ev,16,offset);return new Blob([...parts,...central,end],{type:'application/zip'})}
const originalRender=render;render=function(){originalRender();collectionBanner.hidden=view!=='discover';const query=$('#search').value.toLowerCase();let list=view==='projects'?projects:view==='favorites'?templates.filter(t=>favorites.includes(t.id)):templates;list=list.filter(t=>(category==='All templates'||t.cat===category||category==='Carousels')&&(t.name+' '+t.cat).toLowerCase().includes(query));if(reverse)list=[...list].reverse();$('#grid').querySelectorAll('.card').forEach((card,i)=>{const t=list[i],s=t?.layers?t:t?.slides?.[0];if(!s?.layers)return;const art=card.querySelector('.artwork');art.className='artwork layered';art.querySelector('img')?.remove();art.querySelector('.card-text')?.remove();const c=document.createElement('canvas');c.setAttribute('aria-label',t.name+' preview');art.prepend(c);renderLayerSlide(c,s,t.format||'story');card.querySelector('.card-info small').textContent=`${t.slides?.length||1} slide${(t.slides?.length||1)>1?'s':''}`;card.querySelector('p').textContent=t.description||`${s.layers.filter(l=>l.type==='photo').length} photos · ${s.layers.length} editable layers`})};
$('#hero-create').onclick=()=>openEditor(specials[1]);$('#help').onclick=()=>toast('Choose a layered template. Upload photos, drag elements, add stickers, then export your slides.');render();

$('#search').oninput=()=>render();
blank=function(){originalOpen({...templates.find(t=>t.id===2),name:'Untitled story',title:'Your story\nstarts here.',caption:'MAKE IT YOURS',image:''});design.slides=[design.slides[0]];sync()};
['#new','#start','#blank'].forEach(selector=>$(selector).onclick=()=>blank());
